nodes.command:
node -e "
const fs = require('fs');
const yaml = require('yaml');
const path = '${inputs.project_root}/src/data/zones/${inputs.zone_id}.yaml';
let content = fs.readFileSync(path, 'utf-8');
let doc = yaml.parse(content);
doc.whitebox = doc.whitebox || {};
doc.whitebox.enabled = true;
doc.whitebox.background = { type: 'billboard', width: ${inputs.width}, height: ${inputs.height}, style: '${inputs.zone_type}' };
doc.meta = doc.meta || {};
doc.meta.asset_mode = 'whitebox';
doc.meta.updated_by = 'whitebox-scene-flow';
doc.meta.updated_at = new Date().toISOString();
fs.writeFileSync(path, yaml.stringify(doc));
console.log('Updated:', path);
"

node -e "
const fs = require('fs');
const path = '${inputs.project_root}/src/data/zone-registry.json';
let registry = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path)) : { zones: {} };
registry.zones['${inputs.zone_id}'] = {
  name: '${inputs.zone_name}',
  type: '${inputs.zone_type}',
  chapter: '${inputs.chapter}',
  asset_mode: 'whitebox',
  updated_at: new Date().toISOString()
};
fs.writeFileSync(path, JSON.stringify(registry, null, 2));
console.log('Registry updated for:', '${inputs.zone_id}');
"
